cm = []
his = 0
with open(path) as f:
    for n, line in enumerate(f, 1):
        try: e = json.loads(line)
        except ValueError: continue
        t = e.get('type')
        if t == 'attachment':
            a = e.get('attachment') or {}
            att[a.get('type')] += 1
        elif t == 'user':
            origin[json.dumps(e.get('origin'))[:80]] += 1
            psrc[str(e.get('promptSource'))] += 1
            torig[json.dumps(e.get('turnOrigin'))[:80]] += 1
        elif t == 'assistant':
            for p in (e.get('message') or {}).get('content') or []:
                if isinstance(p, dict) and p.get('type') == 'tool_use':
                    tools[p.get('name')] += 1
        elif t == 'system' and e.get('subtype') == 'compact_boundary':
            cm.append((n, e.get('timestamp'), json.dumps(e.get('compactMetadata'))[:300], str(e.get('content'))[:80]))
        elif t == 'queue-operation':
            qops[e.get('operation')] += 1
print('attachment types', att.most_common())
print('origin', origin.most_common(12))
print('promptSource', psrc.most_common(12))
print('turnOrigin', torig.most_common(12))
print('tools', tools.most_common(60))
print('queue ops', qops.most_common())
for c in cm: print(c)
EOF
