import json, sys, collections
path = sys.argv[1]
seen = collections.Counter()
def shape(o, depth=0):
    if isinstance(o, dict):
        return {k: shape(v, depth+1) for k, v in list(o.items())[:25]}
    if isinstance(o, list):
        return [shape(o[0], depth+1)] if o else []
    if isinstance(o, str):
        return 'str[%d]:%s' % (len(o), o[:60].replace('\n', ' '))
    return o
want = set(sys.argv[2:])
shown = collections.Counter()
with open(path) as f:
    for n, line in enumerate(f, 1):
        try: e = json.loads(line)
        except ValueError: continue
        t = e.get('type')
        key = t
        if t == 'attachment':
            key = 'att:' + str((e.get('attachment') or {}).get('type'))
        if t == 'user':
            o = e.get('origin')
            key = 'user:' + (o.get('kind') if isinstance(o, dict) else 'none')
            if e.get('isCompactSummary'): key = 'user:summary'
        if key in want and shown[key] < 2:
            shown[key] += 1
            print('---', key, 'line', n)
            print(json.dumps(shape(e))[:1800])
EOF
